import { Component, OnDestroy, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { Observable, of, Subscription } from 'rxjs';
import { catchError, switchMap, tap } from 'rxjs/operators';
import { PacientesService } from '../../../services/pacientes.service';
import { Paciente } from '../../../models/paciente.model';

import { Notify } from '../../../../assets/js/layout/extended/messages/notify';

const EMPTY_PACIENTE: Paciente = {
  id: undefined,
  name: '',
  birthDate: '',
  sex: '',
  email: '',
  phone: ''
};

@Component({
  selector: 'app-edit-paciente',
  templateUrl: './edit-paciente.component.html',
  styleUrls: ['./edit-paciente.component.scss']
})
export class EditPacienteComponent implements OnInit, OnDestroy {
  
  currentDate : Date = new Date();
  id: number;
  paciente: Paciente;
  previous: Paciente;
  formGroup: FormGroup;
  isLoading$: Observable<boolean>;
  errorMessage = '';
  tabs = {
    INFOMACOES_PACIENTE_TAB: 0,
    CONTRATOS_TAB: 1,
    LANCAMENTOS_TAB: 2
  };
  activeTabId = this.tabs.INFOMACOES_PACIENTE_TAB; // 0 => Basic info | 1 => Remarks | 2 => Specifications
  private subscriptions: Subscription[] = [];

  constructor(
    private fb: FormBuilder,
    private pacientesService: PacientesService,
    private router: Router,
    private route: ActivatedRoute
  ) { }

  ngOnInit(): void {
    this.isLoading$ = this.pacientesService.isLoading$;
    this.loadPaciente();
  }

  loadPaciente() {
    const sb = this.route.paramMap.pipe(
      switchMap(params => {
        this.id = Number(params.get('id'));
        if (this.id || this.id > 0) {
          return this.pacientesService.getItemById(this.id);
        }
        return of(Object.assign({}, EMPTY_PACIENTE));
      }),
      catchError((errorMessage) => {
        this.errorMessage = errorMessage;
        return of(undefined);
      }),
    ).subscribe((res) => {
      let data = res?.data || res;
      if (!data) {
        this.router.navigate(['/pacientes'], { relativeTo: this.route });
      }

      this.paciente = data;
      this.previous = Object.assign({}, data);
      this.loadForm();
    });
    this.subscriptions.push(sb);
  }

  loadForm() {
    if (!this.paciente) {
      return;
    }

    this.formGroup = this.fb.group({
      name: [this.paciente.name, Validators.compose([Validators.required, Validators.minLength(3), Validators.maxLength(100)])],
      birthDate: [this.paciente.birthDate, Validators.compose([Validators.nullValidator])],
      sex: [this.paciente.sex, Validators.compose([Validators.required])],
      email: [this.paciente.email, Validators.compose([Validators.required, Validators.email])],
      phone: [this.paciente.phone, Validators.compose([Validators.required])]
    });
  }

  reset() {
    if (!this.previous) {
      return;
    }

    this.paciente = Object.assign({}, this.previous);
    this.loadForm();
  }

  save() {
    this.formGroup.markAllAsTouched();
    if (!this.formGroup.valid) {
      return;
    }

    const formValues = this.formGroup.value;
    this.paciente = Object.assign(this.paciente, formValues);
    if (this.id) {
      this.edit();
    } else {
      this.create();
    }
  }

  edit() {
    const sbUpdate = this.pacientesService.update(this.paciente).pipe(
      tap((res) => {
        if(!res?.id){
          this.router.navigate(['/pacientes']) 
          
          new Notify({ 
            message: 'Atualizado com sucesso!', 
            type: 'success' 
          }).show();  
        }
      }),
      catchError((errorMessage) => {
        console.error('UPDATE ERROR', errorMessage);
        return of(this.paciente);
      })
    ).subscribe(res => this.paciente = res);
    this.subscriptions.push(sbUpdate);
  }

  create() {
    const sbCreate = this.pacientesService.create(this.paciente).pipe(
      tap((res) => {
        if(!res?.id){
          this.router.navigate(['/pacientes']) 
          
          new Notify({ 
            message: 'Cadastrado com sucesso!', 
            type: 'success' 
          }).show();  
        }
      }),
      catchError((errorMessage) => {
        console.error('UPDATE ERROR', errorMessage);
        return of(this.paciente);
      })
    ).subscribe(res => this.paciente = res as Paciente);
    this.subscriptions.push(sbCreate);
  }

  changeTab(tabId: number) {
    this.activeTabId = tabId;
  }

  ngOnDestroy() {
    console.log('Cadastrar paciente destruido');
    
    this.subscriptions.forEach(sb => sb.unsubscribe());
  }

  // helpers for View
  isControlValid(controlName: string): boolean {
    const control = this.formGroup.controls[controlName];
    return control.valid && (control.dirty || control.touched);
  }

  isControlInvalid(controlName: string): boolean {
    const control = this.formGroup.controls[controlName];
    return control.invalid && (control.dirty || control.touched);
  }

  controlHasError(validation: string, controlName: string) {
    const control = this.formGroup.controls[controlName];
    return control.hasError(validation) && (control.dirty || control.touched);
  }

  isControlTouched(controlName: string): boolean {
    const control = this.formGroup.controls[controlName];
    return control.dirty || control.touched;
  }
}
